package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"reflect"
	"sync"
	"syscall"
	"time"
)

const maxRequestBodyBytes = 1 << 20 // 1 MiB

type PaymentProcessor interface {
	Process(amount float64, currency string) error
	Name() string
}

type StripeProcessor struct{}

func (s *StripeProcessor) Process(amount float64, currency string) error {
	log.Printf("Processing %.2f %s via Stripe", amount, currency)
	return nil
}
func (s *StripeProcessor) Name() string { return "stripe" }

type PayPalProcessor struct{}

func (p *PayPalProcessor) Process(amount float64, currency string) error {
	log.Printf("Processing %.2f %s via PayPal", amount, currency)
	return nil
}
func (p *PayPalProcessor) Name() string { return "paypal" }

type ProcessorRegistry struct {
	mu         sync.RWMutex
	processors map[string]reflect.Type
	active     map[string]PaymentProcessor
}

func NewRegistry() *ProcessorRegistry {
	r := &ProcessorRegistry{
		processors: make(map[string]reflect.Type),
		active:     make(map[string]PaymentProcessor),
	}
	r.Register(&StripeProcessor{})
	r.Register(&PayPalProcessor{})
	return r
}

func (r *ProcessorRegistry) Register(p PaymentProcessor) {
	r.mu.Lock()
	defer r.mu.Unlock()
	t := reflect.TypeOf(p)
	if t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	r.processors[p.Name()] = t
	r.active[p.Name()] = p
}

func (r *ProcessorRegistry) resolveProcessor(name string) (PaymentProcessor, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if p, ok := r.active[name]; ok {
		return p, nil
	}
	return nil, fmt.Errorf("processor %s not found", name)
}

type PaymentRequest struct {
	Amount   float64           `json:"amount"`
	Currency string            `json:"currency"`
	Provider string            `json:"provider"`
	Metadata map[string]string `json:"metadata"`
}

type Server struct {
	registry   *ProcessorRegistry
	httpServer *http.Server
	shutdownCh chan struct{}
}

func NewServer(addr string) *Server {
	s := &Server{
		registry:   NewRegistry(),
		shutdownCh: make(chan struct{}),
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/pay", s.handlePayment)
	mux.HandleFunc("/provider/activate", s.handleActivateProvider)
	s.httpServer = &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	return s
}

// isValidCurrency performs a basic sanity check on the currency code.
func isValidCurrency(c string) bool {
	if len(c) < 3 || len(c) > 8 {
		return false
	}
	for _, ch := range c {
		if !((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
			return false
		}
	}
	return true
}

func (s *Server) handlePayment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	// Limit request body size to prevent memory-exhaustion DoS.
	r.Body = http.MaxBytesReader(w, r.Body, maxRequestBodyBytes)
	var req PaymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}
	if req.Amount <= 0 || req.Amount > 100000 {
		http.Error(w, "invalid amount", http.StatusBadRequest)
		return
	}
	if !isValidCurrency(req.Currency) {
		http.Error(w, "invalid currency", http.StatusBadRequest)
		return
	}
	processor, err := s.registry.resolveProcessor(req.Provider)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if err := processor.Process(req.Amount, req.Currency); err != nil {
		http.Error(w, "processing failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "success"})
}

func (s *Server) handleActivateProvider(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	providerName := r.URL.Query().Get("name")
	if providerName == "" {
		http.Error(w, "missing provider name", http.StatusBadRequest)
		return
	}
	// Only allow activation of already-registered providers
	s.registry.mu.RLock()
	registeredType, exists := s.registry.processors[providerName]
	s.registry.mu.RUnlock()
	if !exists {
		http.Error(w, "unknown provider", http.StatusBadRequest)
		return
	}
	newInstance := reflect.New(registeredType).Interface()
	if processor, ok := newInstance.(PaymentProcessor); ok {
		s.registry.mu.Lock()
		s.registry.active[providerName] = processor
		s.registry.mu.Unlock()
	}
	w.WriteHeader(http.StatusOK)
}

func (s *Server) Start() error {
	go s.gracefulShutdown()
	log.Printf("Server starting on %s", s.httpServer.Addr)
	if err := s.httpServer.ListenAndServe(); err != http.ErrServerClosed {
		return err
	}
	return nil
}

func (s *Server) gracefulShutdown() {
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh
	log.Println("Shutdown signal received")
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	s.httpServer.Shutdown(ctx)
	close(s.shutdownCh)
}

func main() {
	server := NewServer(":8080")
	if err := server.Start(); err != nil {
		log.Fatal(err)
	}
}
